# Jerarquia de ambitos: grupo de gestion -> suscripcion -> grupo de recursos
asignaciones_por_ambito = {
    "mg-corporativo": ["Ubicaciones permitidas: solo Europa Occidental"],
    "sub-produccion": ["Requerir etiqueta 'centro-costos' en todos los recursos"],
    "rg-app-facturacion": ["Denegar SKU de almacenamiento fuera de Standard_LRS"],
}

exclusiones = {
    "rg-app-facturacion": ["Requerir etiqueta 'centro-costos' en todos los recursos"],
}

jerarquia = ["mg-corporativo", "sub-produccion", "rg-app-facturacion"]

def politicas_efectivas(ambito_objetivo):
    efectivas = []
    for ambito in jerarquia:
        for politica in asignaciones_por_ambito.get(ambito, []):
            if politica in exclusiones.get(ambito_objetivo, []) and ambito != ambito_objetivo:
                continue
            efectivas.append((ambito, politica))
        if ambito == ambito_objetivo:
            break
    return efectivas

for ambito, politica in politicas_efectivas("rg-app-facturacion"):
    print(f"[heredada de {ambito}] {politica}")
